 54	package br.com.loja.pedidos.order;
 55	
 56	import java.time.Clock;
 57	import java.time.Duration;
 58	import java.time.Instant;
 59	import java.time.format.DateTimeParseException;
 60	import java.time.temporal.ChronoUnit;
 61	import java.util.List;
 62	import java.util.UUID;
 63	
 64	import org.springframework.stereotype.Service;
 65	import org.springframework.transaction.annotation.Transactional;
 66	
 67	import br.com.loja.pedidos.catalog.StockService;
 68	import br.com.loja.pedidos.checkout.CheckoutRequest;
 69	import br.com.loja.pedidos.checkout.CheckoutService;
 70	import br.com.loja.pedidos.common.DomainException;
 71	import br.com.loja.pedidos.customer.CustomerRepository;
 72	
 73	/**
 74	 * Operações sobre pedidos. Cada uma trava o pedido, então operações simultâneas
 75	 * (inclusive vindas das duas máquinas) acontecem uma de cada vez.
 76	 * Recusas gravam seus efeitos (cancelamento, registro do aviso) e por isso não desfazem a transação.
 77	 */
 78	@Service
 79	@Transactional(noRollbackFor = DomainException.class)
 80	public class OrderService {
 81	
 82	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 83	
 84	    private final CheckoutService checkout;
 85	    private final OrderRepository orders;
 86	    private final CustomerRepository customers;
 87	    private final StockService stock;
 88	    private final List<OrderEventListener> listeners;
 89	    private final Clock clock;
 90	
 91	    public OrderService(CheckoutService checkout, OrderRepository orders, CustomerRepository customers,
 92	                        StockService stock, List<OrderEventListener> listeners, Clock clock) {
 93	        this.checkout = checkout;
 94	        this.orders = orders;
 95	        this.customers = customers;
 96	        this.stock = stock;
 97	        this.listeners = listeners;
 98	        this.clock = clock;
 99	    }
100	
101	    public Order register(CheckoutRequest request) {
102	        var summary = checkout.calculate(request);
103	        customers.createIfAbsent(request.customer().cpf());
104	        Order order = new Order(UUID.randomUUID().toString(), OrderStatus.AWAITING_PAYMENT,
105	                Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary, request.orderItems(), null,
106	                request.customer().cpf(), request.customer().email());
107	        orders.insert(order);
108	        return order;
109	    }
110	
111	    @Transactional(readOnly = true)
112	    public Order get(String id) {
113	        return orders.find(id).orElseThrow(OrderService::notFound);
114	    }
115	
116	    public Order confirmPayment(String id, String transactionId, String paidAt) {
117	        Order order = lock(id);
118	        if (isBlank(transactionId) || isBlank(paidAt)) {
119	            throw DomainException.unprocessable("INVALID_ORDER");
120	        }
121	        Instant paidInstant = parseInstant(paidAt);
122	
123	        var previous = orders.findPaymentNotice(id, transactionId);
124	        if (previous.isPresent()) {
125	            if (previous.get().isEmpty()) {
126	                return order;
127	            }
128	            throw DomainException.conflict(previous.get());
129	        }
130	        if (!order.status().acceptsPayment()) {
131	            throw DomainException.conflict("OPERATION_NOT_ALLOWED");
132	        }
133	        if (paidInstant.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
134	            throw refuse(order, transactionId, "ORDER_EXPIRED");
135	        }
136	        try {
137	            stock.reserve(order.items());
138	        } catch (DomainException e) {
139	            throw refuse(order, transactionId, e.code());
140	        }
141	        orders.update(id, OrderStatus.PAID, order.trackingCode());
142	        Order paid = withStatus(order, OrderStatus.PAID, order.trackingCode());
143	        listeners.forEach(listener -> listener.paymentConfirmed(paid));
144	        orders.savePaymentNotice(id, transactionId, null);
145	        return paid;
146	    }
147	
148	    public Order ship(String id, String trackingCode) {
149	        Order order = lock(id);
150	        if (isBlank(trackingCode)) {
151	            throw DomainException.unprocessable("INVALID_ORDER");
152	        }
153	        if (!order.status().canShip()) {
154	            throw DomainException.conflict("OPERATION_NOT_ALLOWED");
155	        }
156	        orders.update(id, OrderStatus.SHIPPED, trackingCode);
157	        Order shipped = withStatus(order, OrderStatus.SHIPPED, trackingCode);
158	        listeners.forEach(listener -> listener.shipped(shipped));
159	        return shipped;
160	    }
161	
162	    public Order deliver(String id) {
163	        Order order = lock(id);
164	        if (!order.status().canDeliver()) {
165	            throw DomainException.conflict("OPERATION_NOT_ALLOWED");
166	        }
167	        orders.update(id, OrderStatus.DELIVERED, order.trackingCode());
168	        return withStatus(order, OrderStatus.DELIVERED, order.trackingCode());
169	    }
170	
171	    public Order cancel(String id) {
172	        Order order = lock(id);
173	        if (!order.status().canCancel()) {
174	            throw DomainException.conflict("OPERATION_NOT_ALLOWED");
175	        }
176	        return cancelLocked(order);
177	    }
178	
179	    private DomainException refuse(Order order, String transactionId, String code) {
180	        cancelLocked(order);
181	        orders.savePaymentNotice(order.id(), transactionId, code);
182	        return DomainException.conflict(code);
183	    }
184	
185	    private Order cancelLocked(Order order) {
186	        boolean wasPaid = order.status().paymentReceived();
187	        orders.update(order.id(), OrderStatus.CANCELLED, order.trackingCode());
188	        Order cancelled = withStatus(order, OrderStatus.CANCELLED, order.trackingCode());
189	        if (wasPaid) {
190	            stock.release(order.items());
191	        }
192	        listeners.forEach(listener -> listener.cancelled(cancelled, wasPaid));
193	        return cancelled;
194	    }
195	
196	    private Order lock(String id) {
197	        return orders.findForUpdate(id).orElseThrow(OrderService::notFound);
198	    }
199	
200	    private static Order withStatus(Order order, OrderStatus status, String trackingCode) {
201	        return new Order(order.id(), status, order.createdAt(), order.summary(), order.items(), trackingCode,
202	                order.cpf(), order.email());
203	    }
204	
205	    private static Instant parseInstant(String value) {
206	        try {
207	            return Instant.parse(value);
208	        } catch (DateTimeParseException e) {
209	            throw DomainException.unprocessable("INVALID_ORDER");
210	        }
211	    }
212	
213	    private static boolean isBlank(String value) {
214	        return value == null || value.isBlank();
215	    }
216	
217	    private static DomainException notFound() {
218	        return DomainException.notFound("ORDER_NOT_FOUND");
219	    }
220	}
